package com.champlain.carrental.exception;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.http.converter.HttpMessageNotReadableException;import jakarta.servlet.http.HttpServletRequest;import java.time.LocalDateTime;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;
@RestControllerAdvice public class GlobalExceptionHandler {
private ResponseEntity<Map<String,Object>> error(HttpStatus status,String message,HttpServletRequest req,Map<String,String> fields){Map<String,Object> body=new LinkedHashMap<>();body.put("timestamp",LocalDateTime.now().toString());body.put("status",status.value());body.put("error",status.getReasonPhrase());body.put("message",message);body.put("path",req.getRequestURI());body.put("fieldErrors",fields);return ResponseEntity.status(status).body(body);}
@ExceptionHandler(NotFoundException.class) public ResponseEntity<Map<String,Object>> notFound(NotFoundException e,HttpServletRequest r){return error(HttpStatus.NOT_FOUND,e.getMessage(),r,Map.of());}
@ExceptionHandler({ConflictException.class,DataIntegrityViolationException.class}) public ResponseEntity<Map<String,Object>> conflict(Exception e,HttpServletRequest r){return error(HttpStatus.CONFLICT,e instanceof DataIntegrityViolationException?"Database constraint conflict":e.getMessage(),r,Map.of());}
@ExceptionHandler({IllegalArgumentException.class,HttpMessageNotReadableException.class}) public ResponseEntity<Map<String,Object>> bad(Exception e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,"Invalid request: "+e.getMessage(),r,Map.of());}
@ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e,HttpServletRequest r){Map<String,String> fields=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(f->fields.put(f.getField(),f.getDefaultMessage()));return error(HttpStatus.BAD_REQUEST,"Validation failed",r,fields);}
}